import strawberry
from strawberry.file_uploads import Upload
from strawberry.types import Info

@strawberry.type
class ContractUploadResult:
    contract_id: str
    filename: str
    file_size: int

@strawberry.type
class Mutation:
    @strawberry.mutation
    async def upload_signed_contract(
        self,
        info: Info,
        contract_id: str,
        file: Upload
    ) -> ContractUploadResult:
        user = info.context.get("current_user")
        if not user:
            raise Exception("Authentication required")

        contract_repo = info.context["contract_repository"]
        contract = await contract_repo.get_contract(contract_id)
        if not contract or contract.tenant_id != user.tenant_id:
            raise Exception("Contract not found or unauthorized")

        content = await file.read()
        storage = info.context["storage_service"]
        await storage.save_contract_pdf(contract_id=contract_id, data=content)

        return ContractUploadResult(
            contract_id=contract_id,
            filename=file.filename,
            file_size=len(content)
        )
